use serde_json::Value;
use super::rendering::Text;
use super::render_format::shorten;
use super::renderers_common::{RendererTheme,RenderResultOptions,loc_text,symbol_kind_name,result_details,COLLAPSED_HEAD,EXPANDED_HEAD,PATH_BUDGET};
fn is_document_symbol(symbol:&Value)->bool {symbol.get("range").is_some()}
fn render_document_symbol(symbol:&Value,indent:usize,theme:&dyn RendererTheme)->String {let prefix="  ".repeat(indent);let kind=theme.fg("muted",&format!("({})",symbol_kind_name(symbol.get("kind").and_then(Value::as_u64).unwrap_or(0) as u32)));let name=theme.fg("accent",symbol.get("name").and_then(Value::as_str).unwrap_or(""));let line=symbol.get("range").and_then(|r|r.get("start")).and_then(|s|s.get("line")).and_then(Value::as_u64).unwrap_or(0);let at=theme.fg("dim",&format!("L{}",line+1));let mut lines=vec![format!("{prefix}{name} {kind} {at}")];if let Some(children)=symbol.get("children").and_then(Value::as_array) {for child in children {lines.push(render_document_symbol(child,indent+1,theme));}}lines.join("\n")}
pub fn render_symbols_call(args:&Value,theme:&dyn RendererTheme)->Text {let head=theme.fg("toolTitle",&theme.bold("lsp_symbols "));let scope=theme.fg("muted",&format!("[{}]",args.get("scope").and_then(Value::as_str).unwrap_or("")));if args.get("scope").and_then(Value::as_str)==Some("workspace") {let query=theme.fg("accent",&format!(" \"{}\"",shorten(args.get("query").and_then(Value::as_str).unwrap_or(""),40)));Text::new(format!("{head}{scope}{query}"))} else {let file=theme.fg("accent",&format!(" {}",shorten(args.get("filePath").and_then(Value::as_str).unwrap_or(""),PATH_BUDGET)));Text::new(format!("{head}{scope}{file}"))}}
pub fn render_symbols_result(result:&Value,options:RenderResultOptions,theme:&dyn RendererTheme)->Text {let details=result_details(result);if let Some(error)=details.and_then(|d|d.get("error")).and_then(Value::as_str).filter(|e|!e.is_empty()) {return Text::new(theme.fg("warning",error.split('\n').next().unwrap_or("error")));}let Some(details)=details else {return Text::new(theme.fg("dim","No symbols"));};let total=details.get("totalSymbols").and_then(Value::as_u64).unwrap_or(0);if total==0 {return Text::new(theme.fg("dim","No symbols"));}let symbols=details.get("symbols").and_then(Value::as_array).cloned().unwrap_or_default();let mut summary=theme.fg("success",&format!("{total} symbol{}",if total==1 {""} else {"s"}));summary.push_str(&theme.fg("muted",&format!(" • {}",details.get("scope").and_then(Value::as_str).unwrap_or(""))));
if details.get("truncated").and_then(Value::as_bool).unwrap_or(false) {summary.push_str(&theme.fg("warning"," (truncated)"));}
if !options.expanded {let mut lines=vec![summary];for symbol in symbols.iter().take(COLLAPSED_HEAD) {lines.push(theme.fg("muted",&format!("  {}",symbol.get("name").and_then(Value::as_str).unwrap_or(""))));}if total>COLLAPSED_HEAD as u64 {lines.push(theme.fg("dim",&format!("  … {} more",total-COLLAPSED_HEAD as u64)));}return Text::new(lines.join("\n"));}let mut lines=vec![summary,String::new()];let mut rendered=0usize;for symbol in &symbols {if rendered>=EXPANDED_HEAD {break;}
if is_document_symbol(symbol) {lines.push(render_document_symbol(symbol,0,theme));}else {let kind=theme.fg("muted",&format!("({})",symbol_kind_name(symbol.get("kind").and_then(Value::as_u64).unwrap_or(0) as u32)));let name=theme.fg("accent",symbol.get("name").and_then(Value::as_str).unwrap_or(""));let location=theme.fg("dim",&symbol.get("location").map_or_else(String::new,|l|loc_text(l).unwrap_or_default()));lines.push(format!("{name} {kind}  {location}"));}rendered+=1;}if total>rendered as u64 {lines.push(theme.fg("dim",&format!("… {} more",total-rendered as u64)));}Text::new(lines.join("\n"))}
#[cfg(test)] mod tests {use super::*;use crate::adapter::renderers_common::test_theme::TagTheme;use serde_json::json;
#[test] fn document_call_shows_file_scope(){assert!(render_symbols_call(&json!({"filePath":"/tmp/a.ts","scope":"document"}),&TagTheme).text.ends_with("<accent> /tmp/a.ts</accent>"));}
#[test] fn workspace_call_shows_query(){assert!(render_symbols_call(&json!({"scope":"workspace","query":"Widget"}),&TagTheme).text.ends_with("<accent> \"Widget\"</accent>"));}
#[test] fn workspace_query_is_shortened(){let q="q".repeat(50);assert!(render_symbols_call(&json!({"scope":"workspace","query":q}),&TagTheme).text.ends_with("...\"</accent>"));}
#[test] fn empty_symbols_is_dim(){assert_eq!(render_symbols_result(&json!({"details":{"totalSymbols":0,"symbols":[]}}),RenderResultOptions::default(),&TagTheme).text,"<dim>No symbols</dim>");}
#[test] fn collapsed_lists_names_and_more(){let r=json!({"details":{"totalSymbols":5,"scope":"workspace","truncated":true,"symbols":[{"name":"a"},{"name":"b"},{"name":"c"},{"name":"d"},{"name":"e"}]}});assert!(render_symbols_result(&r,RenderResultOptions::default(),&TagTheme).text.ends_with("<dim>  … 2 more</dim>"));}
#[test] fn expanded_symbol_uses_location(){let r=json!({"details":{"totalSymbols":1,"scope":"workspace","symbols":[{"name":"Widget","kind":12,"location":{"uri":"file:///tmp/a.ts","range":{"start":{"line":4,"character":2}}}}]}});assert!(render_symbols_result(&r,RenderResultOptions {expanded:true,is_partial:false},&TagTheme).text.contains("/tmp/a.ts:5:2"));}
#[test] fn document_symbol_recurses(){let r=json!({"details":{"totalSymbols":1,"scope":"document","symbols":[{"name":"Root","kind":12,"range":{"start":{"line":0}},"children":[{"name":"Child","kind":12,"range":{"start":{"line":2}}}]}]}});assert!(render_symbols_result(&r,RenderResultOptions {expanded:true,is_partial:false},&TagTheme).text.contains("  <accent>Child</accent>"));}
#[test] fn symbols_note_beyond_head(){let symbols=(0..21).map(|i|json!({"name":format!("s{i}"),"kind":12,"location":{"uri":"file:///tmp/a.ts","range":{"start":{"line":0,"character":0}}}})).collect::<Vec<_>>();let r=json!({"details":{"totalSymbols":21,"scope":"workspace","symbols":symbols}});assert!(render_symbols_result(&r,RenderResultOptions {expanded:true,is_partial:false},&TagTheme).text.ends_with("<dim>… 1 more</dim>"));}
#[test] fn symbols_error_warns(){assert_eq!(render_symbols_result(&json!({"details":{"error":"nope"}}),RenderResultOptions::default(),&TagTheme).text,"<warning>nope</warning>");}}
